const assert = require('node:assert/strict');
const fs = require('node:fs');
const { createRequire } = require('node:module');
const lib = createRequire('/Users/aantich/dev/oneringai/package.json')('tsx/cjs') && require('/Users/aantich/dev/oneringai/src/index.ts');
const {Agent, Connector, Vendor, AgentContextNextGen, InMemoryEvidenceStorage, ToolManager, ToolEvidenceMiddleware, ToolCallState} = lib;
const results = {};
const scope = {ownerId:'alice',namespace:'review'};
const raw = {id:'SOURCE_ONLY_COPY',detail:'EXACT_SOURCE_'.repeat(1000)};
const probe = (execute=async()=>raw,blocking=true) => ({definition:{type:'function',blocking,function:{name:'probe',parameters:{type:'object',properties:{}}}},execute,output:{effect:'write',summarize:()=> 'short'}});
const context = (storage=new InMemoryEvidenceStorage({scope}),extra={}) => AgentContextNextGen.create({model:'gpt-4o-mini',agentId:'review',userId:'alice',features:{workingMemory:false,inContextMemory:false,evidence:true},plugins:{evidence:{storage}},...extra});
async function ackWithoutResult(){
 const storage=new InMemoryEvidenceStorage({scope}); const c=context(storage); const realPut=storage.put.bind(storage); storage.put=async()=>{throw new Error('synthetic unavailable')}; const tool=probe(); c.tools.register(tool);
 try {
 c.addUserMessage('query'); c.addAssistantResponse([{type:'message',role:'assistant',content:[{type:'tool_use',id:'call',name:'probe',arguments:'{}'}]}]);
 const report=await c.tools.executeWithOutcome('probe',{}, {callId:'call'});
 c.addToolResults([{tool_use_id:'call',content:raw,state:ToolCallState.COMPLETED,outcome:report.outcome,evidence:report.evidence}]);
 storage.put=realPut;
 const receipt=await new ToolEvidenceMiddleware({storage}).record(tool,{}, {userId:'alice'},report.outcome); // no result, legitimate receipt API
 const acknowledged=await c.acknowledgeToolEvidence('call',receipt.reference);
 c.addAssistantResponse([]);
 const rollover=await c.rollover({preserveRecentTurns:0,summarize:async()=> 'lossy summary'});
 const saved=await storage.readRecord(receipt.reference);
 results.ackWithoutResult={acknowledged,rollover:rollover.performed,storedResultPresent:Object.hasOwn(saved,'result'),rawInHistory:JSON.stringify(c.getConversation()).includes(raw.detail),recordCount:(await storage.list()).entries.length};
 assert.equal(acknowledged,1); assert.equal(rollover.performed,true); assert.equal(Object.hasOwn(saved,'result'),false); assert.equal(results.ackWithoutResult.rawInHistory,false);
 }finally{c.destroy()}
}
async function malformedRestore(){const c=context(); try {
 c.addUserMessage('original'); c.addAssistantResponse([{type:'message',role:'assistant',content:[{type:'output_text',text:'original answer'}]}]);
 const before=JSON.stringify(c.getConversation()); const state=structuredClone(c.getState());
 state.conversation=[{type:'message',role:'user',content:[{type:'input_text',text:'REJECTED_STATE_CONTENT'}]}]; state.systemPrompt='REJECTED_SYSTEM_PROMPT'; state.pluginStates.evidence.recent=[{toolName:'probe',status:'succeeded',completion:'settled',evidence:{status:'stored',effect:'read'}}];
 let error; try{c.restoreState(state)}catch(e){error=e.message}
 results.malformedRestore={error,conversationChanged:before!==JSON.stringify(c.getConversation()),rejectedContentInstalled:JSON.stringify(c.getConversation()).includes('REJECTED_STATE_CONTENT'),systemPrompt:c.getState().systemPrompt};
 assert.ok(error); assert.equal(results.malformedRestore.rejectedContentInstalled,true); const loader=context(undefined,{storage:{load:async()=>({state})}}); try { loader.addUserMessage('loader original'); let loadError;try{await loader.load('malformed')}catch(e){loadError=e.message}; results.malformedLoad={error:loadError,rejectedContentInstalled:JSON.stringify(loader.getConversation()).includes('REJECTED_STATE_CONTENT'),systemPrompt:loader.getState().systemPrompt};assert.ok(loadError);assert.equal(results.malformedLoad.rejectedContentInstalled,true); }finally{loader.destroy()}
 }finally{c.destroy()}}
async function cancellationRace(){
 const found=[];
 for(let depth=1;depth<=45;depth++){
 const storage=new InMemoryEvidenceStorage({scope}); const manager=new ToolManager({toolExecutionTimeout:0}); const controller=new AbortController();
 manager.setToolContext({userId:'alice'}); manager.setEvidenceMiddleware(new ToolEvidenceMiddleware({storage}));
 const later=(n)=>{if(n===0)controller.abort(new DOMException('synthetic cancel','AbortError'));else queueMicrotask(()=>later(n-1));};
 manager.register(probe(async()=>{queueMicrotask(()=>later(depth)); return raw;}));
 try {
 let report,error; try {report=await manager.executeWithOutcome('probe',{}, {signal:controller.signal,callId:'race'})}catch(e){error=e}
 await new Promise(r=>setImmediate(r));
 const entries=(await storage.list()).entries; const records=await Promise.all(entries.map(e=>storage.readRecord(e.reference)));
 if(error && error.outcome?.completion==='settled' && !records.some(r=>Object.hasOwn(r,'result'))){found.push({depth,status:error.outcome.status,completion:error.outcome.completion,recordCount:records.length,resultRecords:records.filter(r=>Object.hasOwn(r,'result')).length});}
 }finally{manager.destroy()}
 }
 results.cancellationRace=found; assert.ok(found.length>0);
}
async function asyncQueue(){
 let calls=0, release; const pending=new Promise(r=>release=r);
 const response=(call)=>({id:'r',object:'response',model:'gpt-4o-mini',created_at:1,status:'completed',output_text:call?'':'done',output:[{type:'message',role:'assistant',content:call?[{type:'tool_use',id:'async-call',name:'probe',arguments:'{}'}]:[{type:'output_text',text:'done'}]}],usage:{input_tokens:1,output_tokens:1,total_tokens:2}});
 const provider={name:'review-provider',capabilities:{text:true},generate:async()=>response(++calls===1),getModelCapabilities:()=>({supportsTools:true,supportsVision:false,supportsJSON:true,supportsJSONSchema:true,maxTokens:128000,maxInputTokens:128000,maxOutputTokens:1024}),validateConfig:async()=>true,listModels:async()=>[],destroy:()=>{}};
 const storage=new InMemoryEvidenceStorage({scope}); storage.put=async()=>{throw new Error('synthetic unavailable')};
 Connector.create({name:'stage03-review',vendor:Vendor.OpenAI,auth:{type:'none'},options:{provider}});
 const agent=Agent.create({connector:'stage03-review',model:'gpt-4o-mini',userId:'alice',tools:[probe(async()=>pending,false)],maxIterations:3,emptyResponseRetry:{enabled:false},asyncTools:{autoContinue:false},context:{model:'gpt-4o-mini',features:{workingMemory:false,inContextMemory:false,evidence:true},plugins:{evidence:{storage}}}});
 try{
 await agent.run('start background'); release(raw);
 for(let i=0;i<100 && agent._asyncResultQueue.length===0;i++)await new Promise(r=>setTimeout(r,1));
 const queuedBefore=agent._asyncResultQueue.length; let firstError,secondError;
 try{await agent.continueWithAsyncResults()}catch(e){firstError=e.message}
 const queuedAfter=agent._asyncResultQueue.length;
 try{await agent.continueWithAsyncResults()}catch(e){secondError=e.message}
 results.asyncQueue={queuedBefore,queuedAfter,firstError,secondError,providerCalls:calls};
 assert.equal(queuedBefore,1); assert.equal(queuedAfter,0); assert.match(firstError,/unacknowledged/); assert.match(secondError,/No async results/);
 }finally{agent.destroy();Connector.remove('stage03-review')}
}
(async()=>{await ackWithoutResult();await malformedRestore();await cancellationRace();await asyncQueue();fs.writeFileSync('/tmp/oneringai-stage03-review-source-repro.json',JSON.stringify(results,null,2)+'\n');console.log(JSON.stringify(results,null,2));})().catch(e=>{console.error(e);process.exitCode=1});

