 const packets=[];const raw={status:'ORIGINAL',ids:['OLD_ID'],rows:'large '.repeat(3000)};
 const response=call=>({id:'r',object:'response',model:'gpt-4o-mini',created_at:1,status:'completed',output_text:call?'':'done',output:[{type:'message',role:'assistant',content:call?[{type:'tool_use',id:'call',name:'probe',arguments:'{}'}]:[{type:'output_text',text:'done'}]}],usage:{input_tokens:1,output_tokens:1,total_tokens:2}});
 const provider={name:'hook-provider',capabilities:{text:true},generate:async opts=>{packets.push(structuredClone(opts));return response(packets.length===1)},getModelCapabilities:()=>({supportsTools:true,supportsVision:false,supportsJSON:true,supportsJSONSchema:true,maxTokens:128000,maxInputTokens:128000,maxOutputTokens:1024}),destroy:()=>{}};
 Connector.create({name:'review-hook',vendor:Vendor.OpenAI,auth:{type:'none'},options:{provider}});const storage=new InMemoryEvidenceStorage({scope:{ownerId:'alice',namespace:'review'}});
 const agent=Agent.create({connector:'review-hook',model:'gpt-4o-mini',userId:'alice',tools:[{definition:{type:'function',function:{name:'probe',parameters:{type:'object',properties:{}}}},execute:async()=>raw,output:{effect:'read',summarize:v=>JSON.stringify({status:v.status,ids:v.ids})}}],hooks:{'after:tool':async ctx=>{ctx.result.content.status='HOST_CHANGED';ctx.result.content.ids=['NEW_ID'];return {modified:{content:ctx.result.content}};}},context:{model:'gpt-4o-mini',features:{workingMemory:false,inContextMemory:false,evidence:true},plugins:{evidence:{storage}}}});
 let completed;agent.on('tool:complete',e=>completed=e.result);
 try{await agent.run('probe');const packet=JSON.stringify(packets[1].input);const result={applicationStatus:completed.content.status,applicationIDs:completed.content.ids,modelHasOldStatus:packet.includes('ORIGINAL'),modelHasOldID:packet.includes('OLD_ID'),modelHasNewID:packet.includes('NEW_ID')};assert.equal(result.applicationStatus,'HOST_CHANGED');assert.equal(result.modelHasOldID,true);assert.equal(result.modelHasNewID,false);fs.writeFileSync('/tmp/oneringai-stage03-review-source-hook.json',JSON.stringify(result,null,2)+'\n');console.log(JSON.stringify(result));}finally{agent.destroy();Connector.remove('review-hook');}
})().catch(e=>{console.error(e);process.exitCode=1});
